import hashlib, json, re
from datetime import datetime, timezone
from pathlib import Path
source = Path('products/services/document-accessibility-paid-lot/raw/uk-tender-feed.json')
raw = source.read_bytes()
assert hashlib.sha256(raw).hexdigest() == '18262fd21a1aed9367bdd87dbeda9b1f3cd8f1b7ad8569bffd214c2deffbc3d9', 'Capture differs from FETCH receipt'
feed = json.loads(raw)
releases = feed['releases']
cutoff = datetime(2026, 11, 27, tzinfo=timezone.utc)
pattern = re.compile(r'accessib|\bWCAG\b|\bPDF/UA\b|screen.reader|document remediation', re.I)
results = []
for release in releases:
    tender = release.get('tender') or {}
    sections = [('tender', tender)] + [(f'lot:{lot.get("id")}', lot) for lot in (tender.get('lots') or [])]
    matches = []
    for section, fields in sections:
        for key in ('title', 'description'):
            text = fields.get(key) or ''
            match = pattern.search(text)
            if match:
                matches.append({'section': section, 'field': key, 'excerpt': text[max(0, match.start()-100):match.end()+160]})
    if not matches:
        continue
    end = (tender.get('tenderPeriod') or {}).get('endDate')
    timing = 'unknown'
    if end:
        try:
            stamp = datetime.fromisoformat(end.replace('Z', '+00:00'))
            if stamp.tzinfo is not None:
                timing = 'after_screen_cutoff' if stamp > cutoff else 'at_or_before_screen_cutoff'
        except ValueError:
            pass
    results.append({'id': release.get('id'), 'ocid': release.get('ocid'), 'release_date': release.get('date'), 'tag': release.get('tag'), 'status': tender.get('status'), 'deadline_as_published': end, 'deadline_screen': timing, 'matches': matches})
report = {'source_receipt': 'TASK-179576101502', 'source_sha256': hashlib.sha256(raw).hexdigest(), 'cutoff_utc': cutoff.isoformat(), 'releases_screened': len(releases), 'matches': results, 'limits': 'Keyword screen of tender and lot titles/descriptions. Matches may concern unrelated accessibility. Verify current deadline, exact scope, eligibility and submission route in the original. Coverage is limited to the captured feed page.'}
out = source.parent.parent / 'director-feed-screen.json'
out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'releases_screened': len(releases), 'matches': len(results), 'output': str(out)}))
